# =====================================================================
# AUTO-BOOTSTRAP MODULAR BAPTISMAL PACKAGE FILES ON DISK
# (Ensures baptismal_app.py, baptismal/*, templates/*, tests/*, and requirements.txt exist on disk)
# =====================================================================
_BAPTISMAL_BUNDLE_B64 = ""

def _bootstrap_modular_baptismal_package_files(force_overwrite: bool = False) -> list[str]:
    written = []
    try:
        base_dir = os.path.dirname(os.path.abspath(__file__)) if "__file__" in globals() else os.getcwd()
        if not force_overwrite and getattr(sys, "_ctg_bap_bootstrap_checked", False):
            return written
        raw_zip = base64.b64decode(_BAPTISMAL_BUNDLE_B64.encode("ascii"))
        with zipfile.ZipFile(io.BytesIO(raw_zip), "r") as zf:
            for member in zf.namelist():
                target_path = os.path.join(base_dir, member)
                os.makedirs(os.path.dirname(target_path) or base_dir, exist_ok=True)
                new_bytes = zf.read(member)
                if not os.path.exists(target_path):
                    with open(target_path, "wb") as out_f:
                        out_f.write(new_bytes)
                    written.append(member)
                elif force_overwrite:
                    try:
                        with open(target_path, "rb") as cur_f:
                            cur_bytes = cur_f.read()
                    except Exception:
                        cur_bytes = None
                    if cur_bytes != new_bytes:
                        with open(target_path, "wb") as out_f:
                            out_f.write(new_bytes)
                    written.append(member)
        sys._ctg_bap_bootstrap_checked = True
    except Exception:
        pass
    return written

if "--unpack-baptismal" not in os.sys.argv:
    _bootstrap_modular_baptismal_package_files(force_overwrite=False)
if "--unpack-baptismal" in os.sys.argv:
    _w = _bootstrap_modular_baptismal_package_files(force_overwrite=True)
    print(f"Unpacked {len(_w)} modular Baptismal System files successfully.")
    raise SystemExit(0)


