def extract_id_from_url(url: str) -> str:
    if not url:
        return ""
    match_d = re.search(r"/d/([a-zA-Z0-9-_]+)", str(url))
    if match_d:
        return match_d.group(1)
    match_f = re.search(r"/folders/([a-zA-Z0-9-_]+)", str(url))
    if match_f:
        return match_f.group(1)
    return str(url).strip()

# ==========================================
# ☁️ GOOGLE DRIVE SERVICE & AUTOMATIC 2027 ROUTING
# ==========================================
LOCAL_SAVED_FAMILIES_JOURNAL = "ctg_saved_families_journal.json"

def _sanitize_user_input_str(val: str) -> str:
    """Prevents CSV/Excel formula injection and strips control characters from untrusted user/OCR strings."""
    s = str(val or "").strip()
    s = re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f]", "", s)
    if s and s[0] in ("=", "+", "-", "@") and not s.startswith(("=IF(", "=UPPER(", "=DATEDIF(", "=COUNTA(")):
        s = s.lstrip("=+-@").strip()
    return s

def _auto_harmonize_family_surname(member_name: str, head_of_family_name: str) -> str:
    """Fixes 1-2 character OCR typos at the end of a family member's surname (e.g. 'Bing Joen G. Paguh/' -> 'Bing Joen G. Paquit')
    by comparing their last token against the Head of Family's verified surname."""
    m_clean = re.sub(r"[/\\|]+$", "", _sanitize_user_input_str(member_name)).strip(" ,.-")
    h_clean = re.sub(r"[/\\|]+$", "", _sanitize_user_input_str(head_of_family_name)).strip(" ,.-")
    if not m_clean or not h_clean:
        return m_clean
    m_parts = m_clean.split()
    h_parts = [p for p in h_clean.split() if p.upper().rstrip(".") not in ("JR", "SR", "II", "III", "IV")]
    if not m_parts or not h_parts:
        return m_clean
    h_last = re.sub(r"[^A-Za-z]", "", h_parts[-1])
    m_last = re.sub(r"[^A-Za-z]", "", m_parts[-1])
    if len(h_last) >= 4 and len(m_last) >= 4 and h_last.upper() != m_last.upper():
        sim = difflib.SequenceMatcher(None, m_last.upper(), h_last.upper()).ratio()
        if sim >= 0.65:
            m_parts[-1] = h_last.title()
            return " ".join(m_parts)
    return m_clean

def _get_vault_secret_key() -> str:
    """Returns a stable secret key derived from GMAIL_CLIENT_SECRET / GMAIL_CLIENT_ID for encrypting the Drive refresh token in Cloud Vaults."""
    for cand_k in ("GMAIL_CLIENT_SECRET", "GMAIL_CLIENT_ID", "NOTION_TOKEN"):
        try:
            if cand_k in st.secrets and str(st.secrets[cand_k]).strip():
                return str(st.secrets[cand_k]).strip()
        except Exception:
            pass
        v_env = os.getenv(cand_k, "")
        if v_env and v_env.strip():
            return v_env.strip()
    return "CTG_MINISTRY_HUB_DEFAULT_VAULT_KEY_2027"

def _encrypt_rt_for_cloud_vault(rt_plain: str, secret_key: str = "") -> str:
    rt_s = str(rt_plain or "").strip()
    if not rt_s:
        return ""
    sk = (secret_key or _get_vault_secret_key()).strip()
    key_bytes = hashlib.sha256(sk.encode("utf-8")).digest()
    pt_bytes = rt_s.encode("utf-8")
    xored = bytes(b ^ key_bytes[i % len(key_bytes)] for i, b in enumerate(pt_bytes))
    return "CTG_RT_VAULT_V1:" + base64.urlsafe_b64encode(xored).decode("ascii")

def _decrypt_rt_from_cloud_vault(enc_blob: str, secret_key: str = "") -> str:
    blob_s = str(enc_blob or "").strip()
    if not blob_s.startswith("CTG_RT_VAULT_V1:"):
        return ""
    raw_b64 = blob_s[len("CTG_RT_VAULT_V1:"):].strip()
    for sk_try in [secret_key, _get_vault_secret_key(), "CTG_MINISTRY_HUB_DEFAULT_VAULT_KEY_2027"]:
        sk = str(sk_try or "").strip()
        if not sk:
            continue
        try:
            key_bytes = hashlib.sha256(sk.encode("utf-8")).digest()
            enc_bytes = base64.urlsafe_b64decode(raw_b64.encode("ascii"))
            pt = bytes(b ^ key_bytes[i % len(key_bytes)] for i, b in enumerate(enc_bytes)).decode("utf-8")
            if (pt.startswith("1//") or pt.startswith("AIza")) and len(pt) > 20:
                return pt
        except Exception:
            continue
    return ""

def _embed_encrypted_rt_into_excel_bytes(excel_bytes: bytes, rt_plain: str = "") -> bytes:
    """Embeds the encrypted Google Drive Refresh Token into a hidden worksheet `_CTG_SYSTEM_VAULT` inside
    CTG_HEADS_TOTAL_MASTER_ORDERED.xlsx so that even if Streamlit Cloud restarts or redeploys after git push,
    downloading the spreadsheet via public HTTP link automatically restores the working Google Drive Refresh Token."""
    if not excel_bytes:
        return excel_bytes
    rt_to_save = str(rt_plain or "").strip()
    if not rt_to_save:
        rt_to_save = str(st.session_state.get("_verified_working_drive_rt", "") or "").strip()
    if not rt_to_save:
        try:
            cfg = load_saved_config() or {}
            rt_to_save = str(cfg.get("GOOGLE_DRIVE_REFRESH_TOKEN", "") or "").strip()
        except Exception:
            rt_to_save = ""
    if not rt_to_save or not rt_to_save.startswith("1//"):
        return excel_bytes
    enc_blob = _encrypt_rt_for_cloud_vault(rt_to_save)
    if not enc_blob:
        return excel_bytes
    try:
        wb = openpyxl.load_workbook(io.BytesIO(excel_bytes))
        if "_CTG_SYSTEM_VAULT" in wb.sheetnames:
            ws_v = wb["_CTG_SYSTEM_VAULT"]
        else:
            ws_v = wb.create_sheet(title="_CTG_SYSTEM_VAULT")
        ws_v.sheet_state = "hidden"
        ws_v.cell(1, 1, enc_blob)
        try:
            g_keys_now = get_valid_gemini_keys()
            if len(g_keys_now) >= 1:
                ws_v.cell(2, 1, _encrypt_rt_for_cloud_vault(g_keys_now[0]))
            if len(g_keys_now) >= 2:
                ws_v.cell(3, 1, _encrypt_rt_for_cloud_vault(g_keys_now[1]))
        except Exception:
            pass
        out = io.BytesIO()
        wb.save(out)
        return out.getvalue()
    except Exception:
        return excel_bytes

_EXTRACTED_VAULT_RT_BY_DIGEST = {}
_DRIVE_SERVICE_INSTANCE_CACHE = {}
_EXCEL_JOURNAL_MERGE_MEMO = {}
_GLOBAL_PARISH_MEMBERS_MEMO = {}
_PWR_CONSOLIDATION_MEMO = {}
_STARTUP_UPGRADES_CHECKED_DIGESTS = set()

def _extract_and_restore_rt_from_excel_bytes(excel_bytes: bytes) -> str:
    """Checks if downloaded Excel bytes contain an encrypted Drive Refresh Token in `_CTG_SYSTEM_VAULT!A1`
    or `HEAD OF FAMILY MASTER!AZ1`, and if so, decrypts and restores it into session_state and ctg_app_cloud_config.json.
    Memoized by MD5 digest for 0.00001s speed on repeat calls."""
    if not excel_bytes or len(excel_bytes) < 1000:
        return ""
    b_dig = hashlib.md5(excel_bytes).hexdigest()
    if b_dig in _EXTRACTED_VAULT_RT_BY_DIGEST:
        cached_rt = _EXTRACTED_VAULT_RT_BY_DIGEST[b_dig]
        if cached_rt and cached_rt not in st.session_state.get("_known_403_gmail_only_tokens", set()):
            st.session_state["_verified_working_drive_rt"] = cached_rt
        return cached_rt
    try:
        wb = openpyxl.load_workbook(io.BytesIO(excel_bytes), read_only=True, data_only=True)
        val = ""
        if "_CTG_SYSTEM_VAULT" in wb.sheetnames:
            ws_v = wb["_CTG_SYSTEM_VAULT"]
            v_rows = list(ws_v.iter_rows(min_row=1, max_row=3, max_col=1, values_only=True))
            if len(v_rows) >= 1 and v_rows[0] and v_rows[0][0] and str(v_rows[0][0]).strip().startswith("CTG_RT_VAULT_V1:"):
                val = str(v_rows[0][0]).strip()
            for g_idx, r_slot in enumerate(v_rows[1:3], 1):
                if r_slot and r_slot[0] and str(r_slot[0]).strip().startswith("CTG_RT_VAULT_V1:"):
                    dec_gk = _decrypt_rt_from_cloud_vault(str(r_slot[0]).strip())
                    if dec_gk and dec_gk.startswith("AIza"):
                        k_name_g = "GEMINI_API_KEY" if g_idx == 1 else "GEMINI_API_KEY_2"
                        if "custom_secrets" in st.session_state and not st.session_state.custom_secrets.get(k_name_g):
                            st.session_state.custom_secrets[k_name_g] = dec_gk
        if not val and "HEAD OF FAMILY MASTER" in wb.sheetnames:
            ws_m = wb["HEAD OF FAMILY MASTER"]
            for row in ws_m.iter_rows(min_row=1, max_row=1, min_col=52, max_col=52, values_only=True):
                if row and row[0] and str(row[0]).strip().startswith("CTG_RT_VAULT_V1:"):
                    val = str(row[0]).strip()
        wb.close()
        if val and val.startswith("CTG_RT_VAULT_V1:"):
            dec_rt = _decrypt_rt_from_cloud_vault(val)
            if dec_rt and dec_rt not in st.session_state.get("_known_403_gmail_only_tokens", set()):
                _EXTRACTED_VAULT_RT_BY_DIGEST[b_dig] = dec_rt
                _silently_cache_recovered_drive_token(dec_rt, val)
                return dec_rt
    except Exception:
        pass
    _EXTRACTED_VAULT_RT_BY_DIGEST[b_dig] = ""
    return ""

def _silently_cache_recovered_drive_token(dec_rt: str, enc_blob: str = ""):
    rt_c = str(dec_rt or "").strip()
    if not rt_c or not rt_c.startswith("1//"):
        return
    st.session_state["_verified_working_drive_rt"] = rt_c
    if "custom_secrets" in st.session_state:
        st.session_state.custom_secrets["GOOGLE_DRIVE_REFRESH_TOKEN"] = rt_c
        st.session_state.custom_secrets["GMAIL_REFRESH_TOKEN"] = rt_c
    try:
        cfg = load_saved_config() or {}
        if cfg.get("GOOGLE_DRIVE_REFRESH_TOKEN") != rt_c:
            cfg["GOOGLE_DRIVE_REFRESH_TOKEN"] = rt_c
            cfg["GMAIL_REFRESH_TOKEN"] = rt_c
            if enc_blob:
                cfg["ENCRYPTED_DRIVE_VAULT_TOKEN"] = enc_blob
            with open(LOCAL_CONFIG_FILE, "w", encoding="utf-8") as f:
                json.dump(cfg, f, indent=2)
    except Exception:
        pass

def _read_raw_toml_secret_from_disk(key_name: str) -> str:
    """Reads a secret key directly from .streamlit/secrets.toml or secrets.toml on disk,
    and automatically repairs any line previously corrupted with ASCII 0x01 by older regex replacements."""
    ctrl_char = chr(1)
    for p_cand in (".streamlit/secrets.toml", "secrets.toml"):
        if os.path.exists(p_cand):
            try:
                with open(p_cand, "r", encoding="utf-8", errors="ignore") as f:
                    txt = f.read()
                if ctrl_char in txt:
                    repaired = re.sub(ctrl_char + r"\s*['\"](1//[^'\"]+)['\"]", r'GMAIL_REFRESH_TOKEN = "\\1"', txt)
                    if repaired != txt:
                        txt = repaired
                        try:
                            with open(p_cand, "w", encoding="utf-8") as fw:
                                fw.write(repaired)
                        except Exception:
                            pass
                m = re.search(rf"^\s*{re.escape(key_name)}\s*=\s*['\"]([^'\"]+)['\"]", txt, flags=re.M)
                if m and m.group(1).strip():
                    return m.group(1).strip()
            except Exception:
                pass
    return ""

def _discover_any_refresh_tokens_on_disk() -> list[str]:
    """Scans .streamlit/secrets.toml, secrets.toml, and .env for any OAuth refresh token starting with 1//."""
    found = []
    for p_cand in (".streamlit/secrets.toml", "secrets.toml", ".env"):
        if os.path.exists(p_cand):
            try:
                with open(p_cand, "r", encoding="utf-8", errors="ignore") as f:
                    txt = f.read()
                for m in re.finditer(r"(1//[A-Za-z0-9_\-]{25,})", txt):
                    tok = m.group(1).strip()
                    if tok not in found:
                        found.append(tok)
            except Exception:
                pass
    return found

def persist_drive_refresh_token_everywhere(new_rt: str, client_id: str = "", client_secret: str = ""):
    """Persists a newly authorized Google Drive + Gmail Refresh Token to session_state,
    ctg_app_cloud_config.json (both plain and encrypted vault form), and local .env without triggering
    a Streamlit watchdog full-app reload."""
    rt_clean = str(new_rt or "").strip()
    if not rt_clean:
        return
    if "custom_secrets" not in st.session_state:
        st.session_state.custom_secrets = {}
    st.session_state.custom_secrets["GMAIL_REFRESH_TOKEN"] = rt_clean
    st.session_state.custom_secrets["GOOGLE_DRIVE_REFRESH_TOKEN"] = rt_clean
    st.session_state["_verified_working_drive_rt"] = rt_clean
    known_403 = st.session_state.get("_known_403_gmail_only_tokens", set())
    if isinstance(known_403, set) and rt_clean in known_403:
        known_403.discard(rt_clean)
    if client_id:
        st.session_state.custom_secrets["GMAIL_CLIENT_ID"] = client_id.strip()
    if client_secret:
        st.session_state.custom_secrets["GMAIL_CLIENT_SECRET"] = client_secret.strip()

    enc_blob = _encrypt_rt_for_cloud_vault(rt_clean, client_secret.strip() if client_secret else "")
    try:
        existing_cfg = load_saved_config() or {}
        existing_cfg["GMAIL_REFRESH_TOKEN"] = rt_clean
        existing_cfg["GOOGLE_DRIVE_REFRESH_TOKEN"] = rt_clean
        if enc_blob:
            existing_cfg["ENCRYPTED_DRIVE_VAULT_TOKEN"] = enc_blob
        bad_list = existing_cfg.get("KNOWN_403_GMAIL_ONLY_TOKENS", [])
        if isinstance(bad_list, list) and rt_clean in bad_list:
            existing_cfg["KNOWN_403_GMAIL_ONLY_TOKENS"] = [x for x in bad_list if x != rt_clean]
        if client_id:
            existing_cfg["GMAIL_CLIENT_ID"] = client_id.strip()
        if client_secret:
            existing_cfg["GMAIL_CLIENT_SECRET"] = client_secret.strip()
        with open(LOCAL_CONFIG_FILE, "w", encoding="utf-8") as f:
            json.dump(existing_cfg, f, indent=2)
    except Exception:
        pass

    ctrl_char = chr(1)
    if os.path.exists(".env"):
        try:
            with open(".env", "r", encoding="utf-8", errors="ignore") as f:
                e_txt = f.read()
            if ctrl_char in e_txt:
                e_txt = re.sub(ctrl_char + r"\s*['\"]?(1//[^'\"\n]+)['\"]?", r'GMAIL_REFRESH_TOKEN="\\1"', e_txt)
            if re.search(r"^\s*GMAIL_REFRESH_TOKEN\s*=", e_txt, flags=re.M):
                e_txt = re.sub(
                    r"^(\s*GMAIL_REFRESH_TOKEN\s*=\s*).*$",
                    rf'\g<1>"{rt_clean}"',
                    e_txt,
                    flags=re.M
                )
            else:
                e_txt = e_txt.rstrip() + f'\nGMAIL_REFRESH_TOKEN="{rt_clean}"\n'
            with open(".env", "w", encoding="utf-8") as f:
                f.write(e_txt)
        except Exception:
            pass

    st.session_state.pop("_drive_needs_scope_upgrade", None)
    try:
        st.cache_resource.clear()
    except Exception:
        pass

def _mark_token_as_403_gmail_only(rt_token: str):
    record_security_audit_event(
        "GOOGLE_DRIVE_AUTH_FAILURE",
        "Google Drive API returned 403 insufficientPermissions (Gmail-only OAuth token scope detected)",
        severity="HIGH",
        outcome="FAILURE",
        denial_reason="OAUTH_403_INSUFFICIENT_SCOPE"
    )
    rt_s = str(rt_token or "").strip()
    if not rt_s:
        return
    if "_known_403_gmail_only_tokens" not in st.session_state or not isinstance(st.session_state["_known_403_gmail_only_tokens"], set):
        st.session_state["_known_403_gmail_only_tokens"] = set()
    st.session_state["_known_403_gmail_only_tokens"].add(rt_s)
    if st.session_state.get("_verified_working_drive_rt") == rt_s:
        st.session_state.pop("_verified_working_drive_rt", None)

def _mark_token_as_verified_drive_working(rt_token: str):
    rt_s = str(rt_token or "").strip()
    if not rt_s:
        return
    prev_verified = st.session_state.get("_verified_working_drive_rt", "")
    st.session_state["_verified_working_drive_rt"] = rt_s
    st.session_state.pop("_drive_needs_scope_upgrade", None)
    if prev_verified != rt_s:
        _silently_cache_recovered_drive_token(rt_s, _encrypt_rt_for_cloud_vault(rt_s))

def get_all_candidate_google_drive_services() -> list:
    """Returns all available Google Drive API service instances across Service Accounts and OAuth Refresh Tokens
    (prioritizing verified Drive tokens and Cloud Vault tokens, and automatically skipping any known 403 Gmail-only token)."""
    services = []
    cfg = {}
    try:
        cfg = load_saved_config() or {}
    except Exception:
        cfg = {}

    # 1. Service Account candidates
    if service_account is not None:
        sa_candidates = [
            st.session_state.get("custom_secrets", {}).get("GOOGLE_SERVICE_ACCOUNT_JSON", ""),
            cfg.get("GOOGLE_SERVICE_ACCOUNT_JSON", ""),
            get_secret("GOOGLE_SERVICE_ACCOUNT_JSON"),
            _read_raw_toml_secret_from_disk("GOOGLE_SERVICE_ACCOUNT_JSON"),
        ]
        try:
            for sec_k in ("GOOGLE_SERVICE_ACCOUNT_JSON", "gcp_service_account", "service_account", "google_service_account"):
                if sec_k in st.secrets:
                    sa_candidates.append(st.secrets[sec_k])
        except Exception:
            pass
        for sa_raw in sa_candidates:
            if not sa_raw:
                continue
            sa_info = None
            if hasattr(sa_raw, "items"):
                sa_info = dict(sa_raw)
            elif isinstance(sa_raw, str) and sa_raw.strip():
                try:
                    sa_info = json.loads(sa_raw)
                except Exception:
                    try:
                        cand_d = ast.literal_eval(sa_raw)
                        if isinstance(cand_d, dict):
                            sa_info = cand_d
                    except Exception:
                        sa_info = None
            if sa_info and isinstance(sa_info, dict) and sa_info.get("private_key"):
                try:
                    creds = service_account.Credentials.from_service_account_info(
                        sa_info, scopes=["https://www.googleapis.com/auth/drive"]
                    )
                    svc_sa = build("drive", "v3", credentials=creds, cache_discovery=False)
                    svc_sa._ctg_rt_token = "SERVICE_ACCOUNT"
                    services.append(svc_sa)
                except Exception:
                    pass

    # 2. OAuth Refresh Token candidates
    g_id_list = [
        st.session_state.get("custom_secrets", {}).get("GMAIL_CLIENT_ID", ""),
        cfg.get("GMAIL_CLIENT_ID", ""),
        _read_raw_toml_secret_from_disk("GMAIL_CLIENT_ID"),
        get_secret("GMAIL_CLIENT_ID"),
        os.getenv("GMAIL_CLIENT_ID", ""),
    ]
    g_sec_list = [
        st.session_state.get("custom_secrets", {}).get("GMAIL_CLIENT_SECRET", ""),
        cfg.get("GMAIL_CLIENT_SECRET", ""),
        _read_raw_toml_secret_from_disk("GMAIL_CLIENT_SECRET"),
        get_secret("GMAIL_CLIENT_SECRET"),
        os.getenv("GMAIL_CLIENT_SECRET", ""),
    ]
    active_cid = next((str(x).strip() for x in g_id_list if str(x or "").strip()), "")
    active_csec = next((str(x).strip() for x in g_sec_list if str(x or "").strip()), "")

    if active_cid and active_csec:
        vault_rt = ""
        if cfg.get("ENCRYPTED_DRIVE_VAULT_TOKEN"):
            vault_rt = _decrypt_rt_from_cloud_vault(cfg.get("ENCRYPTED_DRIVE_VAULT_TOKEN", ""), active_csec)

        raw_rt_candidates = [
            st.session_state.get("_verified_working_drive_rt", ""),
            vault_rt,
            cfg.get("GOOGLE_DRIVE_REFRESH_TOKEN", ""),
            cfg.get("GMAIL_REFRESH_TOKEN", ""),
            st.session_state.get("custom_secrets", {}).get("GOOGLE_DRIVE_REFRESH_TOKEN", ""),
            st.session_state.get("custom_secrets", {}).get("GMAIL_REFRESH_TOKEN", ""),
            _read_raw_toml_secret_from_disk("GOOGLE_DRIVE_REFRESH_TOKEN"),
            _read_raw_toml_secret_from_disk("DRIVE_REFRESH_TOKEN"),
            _read_raw_toml_secret_from_disk("GMAIL_REFRESH_TOKEN"),
        ]
        raw_rt_candidates.extend(_discover_any_refresh_tokens_on_disk())
        try:
            for rk in ("GOOGLE_DRIVE_REFRESH_TOKEN", "DRIVE_REFRESH_TOKEN", "GMAIL_REFRESH_TOKEN"):
                if rk in st.secrets and st.secrets[rk]:
                    raw_rt_candidates.append(str(st.secrets[rk]).strip())
            for _, sv in st.secrets.items():
                if isinstance(sv, str) and sv.strip().startswith("1//"):
                    raw_rt_candidates.append(sv.strip())
                elif isinstance(sv, str) and sv.strip().startswith("CTG_RT_VAULT_V1:"):
                    dec_s = _decrypt_rt_from_cloud_vault(sv.strip(), active_csec)
                    if dec_s:
                        raw_rt_candidates.insert(0, dec_s)
        except Exception:
            pass
        raw_rt_candidates.extend([
            os.getenv("GOOGLE_DRIVE_REFRESH_TOKEN", ""),
            os.getenv("GMAIL_REFRESH_TOKEN", ""),
            GMAIL_REFRESH_TOKEN,
        ])

        known_403_set = st.session_state.get("_known_403_gmail_only_tokens", set())
        if not isinstance(known_403_set, set):
            known_403_set = set()

        # Pass 1: Non-403 tokens first; Pass 2: fallback to known_403_set only if no non-403 tokens exist
        distinct_valid_rts = []
        seen_rts = set()
        for rt_cand in raw_rt_candidates:
            rt_s = str(rt_cand or "").strip()
            if not rt_s or rt_s in seen_rts:
                continue
            seen_rts.add(rt_s)
            distinct_valid_rts.append(rt_s)

        ordered_rts = [r for r in distinct_valid_rts if r not in known_403_set]
        if not ordered_rts:
            ordered_rts = distinct_valid_rts

        for rt_s in ordered_rts:
            cache_k = (active_cid, active_csec, rt_s)
            if cache_k in _DRIVE_SERVICE_INSTANCE_CACHE:
                services.append(_DRIVE_SERVICE_INSTANCE_CACHE[cache_k])
                continue
            try:
                creds = Credentials(
                    token=None,
                    refresh_token=rt_s,
                    token_uri="https://oauth2.googleapis.com/token",
                    client_id=active_cid,
                    client_secret=active_csec
                )
                svc_built = build("drive", "v3", credentials=creds, cache_discovery=False)
                svc_built._ctg_rt_token = rt_s
                _DRIVE_SERVICE_INSTANCE_CACHE[cache_k] = svc_built
                services.append(svc_built)
            except Exception:
                pass
    return services

def get_google_drive_service():
    svcs = get_all_candidate_google_drive_services()
    return svcs[0] if svcs else None

def _verify_drive_folder_id(service, candidate_id: str) -> str:
    """Sinusuri kung ang candidate_id ay nage-exist at naa-access sa Google Drive (supportsAllDrives=True).
    Kung file ID ito sa halip na folder ID, kinukuha ang parent folder ID nito. Kung 404/invalid, ibinabalik ay empty string."""
    if not service or not candidate_id or len(str(candidate_id).strip()) < 10:
        return ""
    cid = str(candidate_id).strip()
    try:
        meta = service.files().get(
            fileId=cid,
            fields="id, name, mimeType, trashed, parents",
            supportsAllDrives=True
        ).execute()
        if meta.get("trashed"):
            return ""
        if meta.get("mimeType") == "application/vnd.google-apps.folder":
            return meta.get("id", "")
        parents = meta.get("parents", [])
        if parents:
            return parents[0]
    except Exception:
        pass
    return ""

def find_drive_folder_by_name(service, folder_name_query: str, parent_id: str = None) -> str:
    if not service or not folder_name_query:
        return ""
    try:
        safe_q = folder_name_query.replace("'", "\\'")
        q_parts = [
            "mimeType='application/vnd.google-apps.folder'",
            "trashed=false",
            f"name contains '{safe_q}'"
        ]
        if parent_id:
            q_parts.append(f"'{parent_id}' in parents")
        res = service.files().list(
            q=" and ".join(q_parts),
            spaces="drive",
            fields="files(id, name)",
            pageSize=25,
            supportsAllDrives=True,
            includeItemsFromAllDrives=True
        ).execute()
        files = res.get("files", [])
        return files[0]["id"] if files else ""
    except Exception:
        return ""

KNOWN_PARISH_DRIVE_FOLDER_IDS = {
    "POBLACION PARISH": "1MLBg_h0nimbTCtcgmq0i8ymXuJy6QK-1",
}

def _resolve_best_subfolder_for_month(service, parish_folder_id: str, month_name: str = "") -> str:
    """Kung mayroong month subfolder sa loob ng Parish Folder (hal. '01. January Pwr. 2027' sa loob ng 'POBLACION PARISH'),
    ibinabalik ang ID ng month subfolder; kung wala, ibinabalik mismo ang parish_folder_id."""
    if not service or not parish_folder_id or not month_name:
        return parish_folder_id
    try:
        res_sub = service.files().list(
            q=f"'{parish_folder_id}' in parents and mimeType='application/vnd.google-apps.folder' and trashed=false",
            spaces="drive",
            fields="files(id, name)",
            pageSize=50,
            supportsAllDrives=True,
            includeItemsFromAllDrives=True
        ).execute()
        m_low = month_name.strip().lower()
        m_idx = (MONTHS_2027.index(month_name) + 1) if month_name in MONTHS_2027 else 0
        m_num_prefix = f"{m_idx:02d}." if m_idx > 0 else ""
        for sf in res_sub.get("files", []):
            sf_name_low = sf.get("name", "").strip().lower()
            if m_low in sf_name_low or (m_num_prefix and sf_name_low.startswith(m_num_prefix)):
                return sf["id"]
    except Exception:
        pass
    return parish_folder_id

def get_or_create_parish_subfolder(service, parent_folder_id: str, parish_name: str, month_name: str = "") -> str:
    """Hinahanap ang eksaktong Parish Folder (at Month subfolder kung mayroon, tulad ng '01. January Pwr. 2027')
    gamit ang Saved Links sa App, Known Parish Folder IDs, o direktang paghahanap sa Google Drive nang walang 404 error."""
    if not service:
        return ""
    clean_parish = (parish_name or "").upper().replace("PARISH", "").replace("CHAPTER", "").strip()
    short_keyword = clean_parish.replace("NORTE", "").strip()

    # 1. Tingnan muna sa Saved Google Drive Links Registry kung may inilagay na partikular na link ang Admin para sa Parokyang ito
    try:
        saved_links = list(reversed(load_saved_drive_links_registry()))
        for item in saved_links:
            u_str = str(item.get("url", "")).strip()
            if not u_str:
                continue
            lbl_up = str(item.get("label", "")).upper()
            p_scope_up = str(item.get("parish", "")).upper()
            m_scope_up = str(item.get("month", "")).upper()
            if clean_parish and (clean_parish in p_scope_up or clean_parish in lbl_up or (short_keyword and short_keyword in lbl_up)):
                cand_id = _verify_drive_folder_id(service, extract_id_from_url(u_str))
                if cand_id:
                    if month_name and month_name.upper() in (m_scope_up + " " + lbl_up):
                        return cand_id
                    return _resolve_best_subfolder_for_month(service, cand_id, month_name)
    except Exception:
        pass

    # 2. Tingnan kung may Known Folder ID para sa Parokya (hal. POBLACION PARISH -> 1MLBg_h0nimbTCtcgmq0i8ymXuJy6QK-1)
    if parish_name and parish_name.upper().strip() in KNOWN_PARISH_DRIVE_FOLDER_IDS:
        known_id = _verify_drive_folder_id(service, KNOWN_PARISH_DRIVE_FOLDER_IDS[parish_name.upper().strip()])
        if known_id:
            return _resolve_best_subfolder_for_month(service, known_id, month_name)

    # 3. I-verify kung accessible ang parent_folder_id; kung hindi (404), hanapin sa Saved Links o sa buong Google Drive
    valid_parent_id = _verify_drive_folder_id(service, parent_folder_id)
    if not valid_parent_id:
        try:
            for item in reversed(load_saved_drive_links_registry()):
                cat_s = str(item.get("category", ""))
                lbl_s = str(item.get("label", ""))
                u_s = str(item.get("url", "")).strip()
                if u_s and ("Upload" in cat_s or "Folder" in cat_s or "Upload" in lbl_s):
                    cid = _verify_drive_folder_id(service, extract_id_from_url(u_s))
                    if cid:
                        valid_parent_id = cid
                        break
        except Exception:
            pass

    if not valid_parent_id:
        valid_parent_id = (
            find_drive_folder_by_name(service, "Upload the Image/Excel File here")
            or find_drive_folder_by_name(service, "Upload the Image")
            or find_drive_folder_by_name(service, "CTG Ministry Hub")
        )

    # 4. Kung may valid_parent_id, tingnan kung ang parent_id mismo ay ang Parish Folder na, o hanapin sa loob nito
    if valid_parent_id and parish_name:
        try:
            p_meta = service.files().get(fileId=valid_parent_id, fields="id, name", supportsAllDrives=True).execute()
            p_meta_up = p_meta.get("name", "").upper()
            if clean_parish and (clean_parish in p_meta_up or (short_keyword and short_keyword in p_meta_up)):
                return _resolve_best_subfolder_for_month(service, valid_parent_id, month_name)

            res = service.files().list(
                q=f"'{valid_parent_id}' in parents and mimeType='application/vnd.google-apps.folder' and trashed=false",
                spaces="drive",
                fields="files(id, name)",
                pageSize=50,
                supportsAllDrives=True,
                includeItemsFromAllDrives=True
            ).execute()
            folders = res.get("files", [])
            for folder in folders:
                f_up = folder["name"].upper().strip()
                f_clean = re.sub(r"^\d+[\.\-\s]*", "", f_up).replace("PARISH", "").replace("CHAPTER", "").strip()
                if (
                    f_up == parish_name.upper().strip()
                    or f_clean == clean_parish
                    or f_clean == short_keyword
                    or (clean_parish and clean_parish in f_up)
                    or (short_keyword and short_keyword in f_up)
                ):
                    return _resolve_best_subfolder_for_month(service, folder["id"], month_name)
        except Exception:
            pass

    # 5. Hanapin nang direkta ang Parish Folder sa buong Google Drive (hal. 'POBLACION PARISH', 'MALANAS PARISH', 'LIPAY PARISH')
    if parish_name:
        direct_p_id = (
            find_drive_folder_by_name(service, parish_name)
            or (find_drive_folder_by_name(service, f"{short_keyword} PARISH") if short_keyword else "")
            or (find_drive_folder_by_name(service, clean_parish) if clean_parish else "")
        )
        if direct_p_id:
            return _resolve_best_subfolder_for_month(service, direct_p_id, month_name)

    # 6. Kung wala pa ring nahanap na folder, gumawa ng bagong folder sa loob ng valid_parent_id o sa My Drive root
    try:
        if not valid_parent_id:
            root_created = service.files().create(
                body={"name": "Upload the Image/Excel File here!", "mimeType": "application/vnd.google-apps.folder"},
                fields="id",
                supportsAllDrives=True
            ).execute()
            valid_parent_id = root_created.get("id", "")
        if parish_name and valid_parent_id:
            p_created = service.files().create(
                body={"name": parish_name, "mimeType": "application/vnd.google-apps.folder", "parents": [valid_parent_id]},
                fields="id",
                supportsAllDrives=True
            ).execute()
            return p_created.get("id", valid_parent_id)
    except Exception:
        pass
    return valid_parent_id or ""

def upload_file_to_google_drive(file_bytes, filename, mime_type="image/jpeg", parent_folder_url="", parish_name="", month_name=""):
    service = get_google_drive_service()
    if service is None:
        return None, "Error: Kulang ang Google Drive/Gmail credentials sa App Settings."
    try:
        raw_folder_id = extract_id_from_url(parent_folder_url)
        target_folder_id = (
            get_or_create_parish_subfolder(service, raw_folder_id, parish_name, month_name)
            if parish_name
            else _verify_drive_folder_id(service, raw_folder_id)
        )
        file_metadata = {"name": filename}
        if target_folder_id:
            file_metadata["parents"] = [target_folder_id]
        media = MediaIoBaseUpload(io.BytesIO(file_bytes), mimetype=mime_type or "application/octet-stream", resumable=True)
        try:
            file = service.files().create(
                body=file_metadata,
                media_body=media,
                fields="id, webViewLink",
                supportsAllDrives=True
            ).execute()
            return file.get("webViewLink"), f"Matagumpay na na-upload sa Google Drive folder ng {parish_name or 'CTG'}!"
        except Exception as inner_ex:
            # Kung nag-404 o 403 sa partikular na parent folder, awtomatikong mag-fallback sa sariling Parish folder sa My Drive root
            if "404" in str(inner_ex) or "notFound" in str(inner_ex) or "403" in str(inner_ex):
                fallback_parent_id = get_or_create_parish_subfolder(service, "", parish_name, month_name) if parish_name else ""
                fb_meta = {"name": filename}
                if fallback_parent_id:
                    fb_meta["parents"] = [fallback_parent_id]
                media_fb = MediaIoBaseUpload(io.BytesIO(file_bytes), mimetype=mime_type or "application/octet-stream", resumable=True)
                try:
                    file_fb = service.files().create(
                        body=fb_meta,
                        media_body=media_fb,
                        fields="id, webViewLink",
                        supportsAllDrives=True
                    ).execute()
                    return file_fb.get("webViewLink"), f"Matagumpay na na-upload sa Google Drive folder ng {parish_name or 'CTG'}!"
                except Exception:
                    media_root = MediaIoBaseUpload(io.BytesIO(file_bytes), mimetype=mime_type or "application/octet-stream", resumable=True)
                    file_root = service.files().create(
                        body={"name": filename},
                        media_body=media_root,
                        fields="id, webViewLink",
                        supportsAllDrives=True
                    ).execute()
                    return file_root.get("webViewLink"), f"Matagumpay na na-upload sa iyong Google Drive ({filename})!"
            raise inner_ex
    except Exception as e:
        err_str = str(e)
        if "403" in err_str or "insufficientPermissions" in err_str:
            return None, (
                "Google Drive Permission Error (403): Ang iyong kasalukuyang Refresh Token ay pang-Gmail lamang. "
                "Pumunta sa '🛠️ App Settings -> 🔑 API & Google Drive / Gmail Credentials' at gamitin ang 'One-Click Google Drive + Gmail Token Generator' upang mabuksan ang Google Drive write access."
            )
        return None, f"Google Drive Upload Error: {err_str}"

def build_stitched_family_form_jpeg_bytes(page_previews: list[dict]) -> bytes:
    """Combines multi-page registration form images (e.g. 4 pages from a PDF) into a single high-clarity vertical JPEG image
    so that the complete Form Image (.jpg) can be automatically uploaded to the Parish's Google Drive folder alongside the PDF."""
    if not page_previews:
        return b""
    try:
        pil_pages = []
        for pp in page_previews:
            im = Image.open(io.BytesIO(pp["bytes"])).convert("RGB")
            pil_pages.append(im)
        if not pil_pages:
            return b""
        if len(pil_pages) == 1:
            ob = io.BytesIO()
            pil_pages[0].save(ob, format="JPEG", quality=88)
            return ob.getvalue()
        target_w = max(im.width for im in pil_pages)
        resized_pages = []
        total_h = 0
        for im in pil_pages:
            if im.width != target_w:
                new_h = int(im.height * (target_w / float(im.width)))
                im = im.resize((target_w, new_h), Image.Resampling.BICUBIC)
            resized_pages.append(im)
            total_h += im.height + 12
        canvas = Image.new("RGB", (target_w, max(1, total_h - 12)), (255, 255, 255))
        y_off = 0
        for im in resized_pages:
            canvas.paste(im, (0, y_off))
            y_off += im.height + 12
        ob = io.BytesIO()
        canvas.save(ob, format="JPEG", quality=86)
        return ob.getvalue()
    except Exception:
        return page_previews[0].get("bytes", b"") if page_previews else b""

def upload_member_image_to_parish_database_folder(file_bytes: bytes, filename: str, mime_type: str, parish_name: str) -> tuple[str, str]:
    save_uploaded_form_to_external_hard_drive(file_bytes, filename, parish_name)
    """
    Routes any member registration photo, stitched form JPEG, or PDF uploaded by Parish Leaders / Admins
    directly to that Parish's dedicated subfolder inside 'CTG MEMBERS DATABASE ALL PARISH'
    (Parent Folder ID: 1RXOTB6iA0jgcsOf1kE8wn3V8DHVduvH0 -> Subfolders 1..10 per Parish).
    Tries direct creation in target_subfolder_id across all candidate Google Drive services first (0 files().list calls required!).
    """
    services = get_all_candidate_google_drive_services()
    if not services:
        return None, "Error: Kulang ang Google Drive/Gmail credentials sa App Settings."

    p_clean = (parish_name or "").upper().strip()
    target_subfolder_id = CTG_MEMBERS_DB_PARISH_SUBFOLDER_IDS.get(p_clean, "")
    if not target_subfolder_id:
        for p_k, f_id in CTG_MEMBERS_DB_PARISH_SUBFOLDER_IDS.items():
            if normalize_parish_match(p_clean, p_k):
                target_subfolder_id = f_id
                break

    last_err = ""
    any_scope_403 = False
    for service in services:
        this_svc_403 = False
        # 1. Direct upload to the exact Parish Subfolder ID (no files().get or files().list needed!)
        for candidate_parent in [target_subfolder_id, ALL_PARISH_DB_FOLDER_ID, APP_STORAGE_FOLDER_ID]:
            if not candidate_parent:
                continue
            try:
                media = MediaIoBaseUpload(io.BytesIO(file_bytes), mimetype=mime_type or "image/jpeg", resumable=True)
                created = service.files().create(
                    body={"name": filename, "parents": [candidate_parent]},
                    media_body=media,
                    fields="id, webViewLink",
                    supportsAllDrives=True
                ).execute()
                _mark_token_as_verified_drive_working(getattr(service, "_ctg_rt_token", ""))
                return created.get("webViewLink") or f"https://drive.google.com/drive/folders/{candidate_parent}", f"Matagumpay na na-upload ang `{filename}` sa CTG MEMBERS DATABASE ALL PARISH → {parish_name}!"
            except Exception as e1:
                last_err = str(e1)
                if "insufficientPermissions" in last_err or "insufficient authentication scopes" in last_err:
                    _mark_token_as_403_gmail_only(getattr(service, "_ctg_rt_token", ""))
                    this_svc_403 = True
                    any_scope_403 = True
                    break

        if this_svc_403:
            continue

        # 2. Fallback: upload to My Drive root if subfolder isn't shared with the token's account yet
        try:
            media_root = MediaIoBaseUpload(io.BytesIO(file_bytes), mimetype=mime_type or "image/jpeg", resumable=True)
            created_root = service.files().create(
                body={"name": filename},
                media_body=media_root,
                fields="id, webViewLink",
                supportsAllDrives=True
            ).execute()
            _mark_token_as_verified_drive_working(getattr(service, "_ctg_rt_token", ""))
            return created_root.get("webViewLink"), f"Matagumpay na na-upload sa Google Drive (`{filename}`)!"
        except Exception as e2:
            last_err = str(e2)
            if "insufficientPermissions" in last_err or "insufficient authentication scopes" in last_err:
                _mark_token_as_403_gmail_only(getattr(service, "_ctg_rt_token", ""))
                any_scope_403 = True

    # Queue the file locally so it can be auto-flushed to Google Drive as soon as Master Admin activates the Drive token!
    try:
        q_dir = "pending_drive_uploads"
        os.makedirs(q_dir, exist_ok=True)
        q_file_path = os.path.join(q_dir, re.sub(r"[^A-Za-z0-9._\- ]", "_", filename))
        with open(q_file_path, "wb") as fq:
            fq.write(file_bytes)
        q_meta_path = os.path.join(q_dir, "queue_manifest.json")
        q_list = []
        if os.path.exists(q_meta_path):
            with open(q_meta_path, "r", encoding="utf-8") as fm:
                q_list = json.load(fm) or []
        q_list = [x for x in q_list if x.get("filename") != filename]
        q_list.append({
            "path": q_file_path,
            "filename": filename,
            "mime_type": mime_type or "application/pdf",
            "parish_name": parish_name
        })
        with open(q_meta_path, "w", encoding="utf-8") as fm:
            json.dump(q_list, fm, indent=2)
    except Exception:
        pass

    if any_scope_403:
        st.session_state["_drive_needs_scope_upgrade"] = True
        return None, (
            "⚠️ Naka-queue na ang Form File/Image para sa Google Drive! (Kailangan lang i-refresh ni Master Admin ang Google Drive Token sa '🛠️ App Settings -> 🔑 API & Google Drive / Gmail Credentials' dahil naka-Gmail-only scope ang token matapos mag-restart ang Streamlit Cloud)."
        )
    return None, f"⚠️ Hindi pa na-upload sa Google Drive Folder ({last_err[:120]})."

