def _clean_ocr_place_names(raw_place: str, matched_parish: str = "") -> str:
    """Auto-corrects common OCR handwriting misreads of CTG barangays, municipalities, and provinces
    (e.g. '4 pay Nurte' / 'Lipay Hurle' -> 'Lipay Norte', 'San Gabnel' -> 'San Gabriel', 'La Unlon' -> 'La Union')."""
    s = _clean_cell_str(raw_place)
    if not s:
        return ""
    replacements = [
        (r"\b(?:4\s*pay|L\s*pay|L[1il]p[ae]y|L[1il]pal)\s*(?:N[uo][rk][tl]e|H[uo]r[tl]e|Work|Norte)\b", "Lipay Norte"),
        (r"\bL[1il]pay\s*Work\b", "Lipay Norte"),
        (r"\b(?:San|Van)\s*(?:Gabr?[1in]el|Gabnel|Cabriel|Gebriel)\b", "San Gabriel"),
        (r"\bLa\s*Un[1il][od]n\b", "La Union"),
        (r",?\s*\bL\.?U\.?\b", ", La Union"),
        (r"\bPoblac[1il]on\b", "Poblacion"),
        (r"\bMalanas\b", "Malanas"),
        (r"\bDuplas\b", "Duplas"),
        (r"\bSud[1il]pen\b", "Sudipen"),
        (r"\bSant[1il]ago\b", "Santiago"),
        (r"\bIlocos\s*Sur\b", "Ilocos Sur"),
        (r"\bCaba\b", "Caba"),
        (r"\bAndabuen\b", "Andabuen"),
        (r"\bBenito\s*Soliven\b", "Benito Soliven"),
        (r"\bIsabela\b", "Isabela"),
        (r"\bApayao\b", "Apayao"),
        (r"\bMan[1il]la\b", "Manila"),
        (r"\bHong\s*Kong\b", "Hong Kong"),
    ]
    for pat, rep in replacements:
        s = re.sub(pat, rep, s, flags=re.I)
    return s.strip()

def _auto_correct_person_name_with_filename(ocr_name: str, filename_clean_name: str) -> str:
    """Auto-corrects OCR handwriting typos in Head of Family name (such as 'ALPREAD JR. TADINA')
    using the clean person name from the PDF filename ('Alfredo Tadina') while preserving suffixes/middle initials like 'Jr.'."""
    ocr_s = _clean_cell_str(ocr_name)
    file_s = _clean_cell_str(filename_clean_name)
    if not ocr_s:
        return file_s
    if not file_s:
        return ocr_s
    ocr_tokens = ocr_s.split()
    file_tokens = file_s.split()
    corrected_tokens = []
    for tok in ocr_tokens:
        tok_clean = re.sub(r"[^A-Za-z]", "", tok).upper()
        if len(tok_clean) <= 2 or tok_clean in ("JR", "SR", "II", "III", "IV"):
            if tok_clean in ("JR", "SR", "MA"):
                corrected_tokens.append(f"{tok_clean.title()}.")
            elif tok_clean in ("DE", "LA", "DA", "DI", "FE"):
                corrected_tokens.append(tok_clean.title())
            elif len(tok_clean) == 1:
                corrected_tokens.append(f"{tok_clean}.")
            else:
                corrected_tokens.append(tok_clean)
            continue
        best_match = None
        best_ratio = 0.0
        for f_tok in file_tokens:
            f_clean = re.sub(r"[^A-Za-z]", "", f_tok).upper()
            if len(f_clean) >= 3:
                r = difflib.SequenceMatcher(None, tok_clean, f_clean).ratio()
                if r > best_ratio:
                    best_ratio = r
                    best_match = f_tok
        if best_match and best_ratio >= 0.62:
            corrected_tokens.append(best_match.title())
        else:
            corrected_tokens.append(tok.title())
    return " ".join(corrected_tokens).strip()

def _normalize_phone_sim_number(raw_phone: str) -> str:
    """Normalizes handwritten or OCR-extracted Contact Number / Cellphone Number / SIM Number / Mobile Number
    (e.g. 'O945-632-5668', '+63 950 469 5484', '0981 265 8016') into clean digits."""
    s = _clean_cell_str(raw_phone)
    if not s:
        return ""
    # Replace common OCR letter-for-digit lookalikes when adjacent to digits
    s_fix = re.sub(r"(?<=\d)[Oo]|^[Oo](?=9\d)", "0", s)
    s_fix = re.sub(r"(?<=\d)[Il]|[Il](?=\d)", "1", s_fix)
    m_ph = re.search(r"(?:\+?63|0)(9\d{2}[\s\-.]?\d{3}[\s\-.]?\d{4})", s_fix)
    if m_ph:
        return "0" + re.sub(r"\D", "", m_ph.group(1))
    digits = re.sub(r"\D", "", s_fix)
    if len(digits) == 11 and digits.startswith("09"):
        return digits
    if len(digits) == 12 and digits.startswith("639"):
        return "0" + digits[2:]
    if len(digits) == 10 and digits.startswith("9"):
        return "0" + digits
    if 8 <= len(digits) <= 13:
        return digits
    return ""

def _normalize_handwritten_date_to_iso(raw_date: str, age_hint: str = "") -> str:
    """Converts handwritten dates like '01-10-58', '09-11-60', 'Jan 10, 1987', '11-17-1999',
    and compact/OCR-garbled digit dates like '0712202' (07-12-2012) or '11023018' (11-02-2018) to 'YYYY-MM-DD'."""
    s = _clean_cell_str(raw_date)
    if not s:
        return ""
    s_clean = s.strip()
    if re.match(r"^\d{4}-\d{2}-\d{2}$", s_clean):
        yr_chk = int(s_clean[:4])
        if 3000 <= yr_chk <= 3027:
            return f"{yr_chk - 1000:04d}" + s_clean[4:]
        return s_clean

    # Fix 4-digit year typo 30xx -> 20xx or 29xx -> 19xx inside separated dates (e.g. 11-02-3018 -> 11-02-2018)
    s_clean = re.sub(r"\b30([012]\d)\b", r"20\1", s_clean)
    s_clean = re.sub(r"\b29([2-9]\d)\b", r"19\1", s_clean)

    # Compact 7- or 8-digit numeric dates without separators (e.g. '11022018', '11023018', '07122012', '0712202')
    digits_only = re.sub(r"\D", "", s_clean)
    if len(digits_only) == 8 and digits_only == s_clean:
        mm_v, dd_v, yyyy_v = int(digits_only[:2]), int(digits_only[2:4]), int(digits_only[4:8])
        if 3000 <= yyyy_v <= 3027:
            yyyy_v -= 1000
        elif 2920 <= yyyy_v <= 2999:
            yyyy_v -= 1000
        if mm_v > 12 and dd_v <= 12:
            mm_v, dd_v = dd_v, mm_v
        if 1 <= mm_v <= 12 and 1 <= dd_v <= 31 and 1910 <= yyyy_v <= 2027:
            return f"{yyyy_v:04d}-{mm_v:02d}-{dd_v:02d}"
    elif len(digits_only) == 7 and digits_only == s_clean:
        mm_v, dd_v, yyy_s = int(digits_only[:2]), int(digits_only[2:4]), digits_only[4:7]
        if mm_v > 12 and dd_v <= 12:
            mm_v, dd_v = dd_v, mm_v
        yyyy_v = 0
        if str(age_hint or "").isdigit() and 0 <= int(age_hint) <= 105:
            yyyy_v = 2026 - int(age_hint)
        elif yyy_s.startswith("20"):
            yyyy_v = 2012 if yyy_s == "202" else int(yyy_s + "0")
        elif yyy_s.startswith("19"):
            yyyy_v = int(yyy_s + "0")
        if 1 <= mm_v <= 12 and 1 <= dd_v <= 31 and 1910 <= yyyy_v <= 2027:
            return f"{yyyy_v:04d}-{mm_v:02d}-{dd_v:02d}"

    # Direct MM-DD-YY or MM/DD/YY or MM.DD.YY 2-digit year handling (e.g. 01-10-58 -> 1958-01-10)
    m_2y = re.match(r"^(\d{1,2})[-/.](\d{1,2})[-/.](\d{2})$", s_clean)
    if m_2y:
        mm_v, dd_v, yy_v = int(m_2y.group(1)), int(m_2y.group(2)), int(m_2y.group(3))
        if mm_v > 12 and dd_v <= 12:
            mm_v, dd_v = dd_v, mm_v
        yyyy_v = (1900 + yy_v) if yy_v >= 27 else (2000 + yy_v)
        if 1 <= mm_v <= 12 and 1 <= dd_v <= 31:
            return f"{yyyy_v:04d}-{mm_v:02d}-{dd_v:02d}"
    s_norm = re.sub(r"\s+", " ", s_clean.replace(".", " ").replace(",", ", ")).strip()
    try:
        dt = pd.to_datetime(s_norm, errors="coerce")
        if pd.notna(dt):
            yr = dt.year
            if 3000 <= yr <= 3027:
                yr -= 1000
            elif yr > 2027:
                yr -= 100
            if 1910 <= yr <= 2027:
                return f"{yr:04d}-{dt.month:02d}-{dt.day:02d}"
    except Exception:
        pass
    if re.match(r"^\d{5,}$", s_clean):
        return ""
    return s_clean

def _auto_clean_and_complete_family_records(records: list[dict], default_parish: str, source_filename: str = "") -> list[dict]:
    """Auto-fixes and completes all household & family member fields across an extracted or edited family batch:
    - Auto-corrects Head of Family spelling against the PDF filename (e.g. 'ALPREAD JR. TADINA' -> 'Alfredo Jr. Tadina')
    - Normalizes dates to YYYY-MM-DD and auto-computes Age & Category (KIDS/YOUTH/ADULT/SENIOR CITIZEN)
    - Infers Sex & Civil Status from Relationship (e.g. WIFE -> FEMALE/MARRIED, HUSBAND -> MALE/MARRIED, DAUGHTER -> FEMALE, SON -> MALE)
    - Propagates Parish, Family ID, Area/Zone, Address, Barangay, City, Province, ZIP, Emergency Contact, and Remarks across all family members."""
    if not records:
        return []
    first = records[0].copy()
    p_name = _clean_cell_str(first.get("Parish", default_parish)) or default_parish
    matched_p = default_parish
    for p_cand in PARISH_ORDER:
        if normalize_parish_match(p_name, p_cand):
            matched_p = p_cand
            break
    is_hk = (matched_p == "HONGKONG PARISH")

    valid_records = [
        r for r in records
        if isinstance(r, dict) and _clean_cell_str(r.get("Full Name", "")) and not _is_junk_ocr_header_name(_clean_cell_str(r.get("Full Name", "")))
    ]
    if not valid_records:
        return []
    records = valid_records
    first = records[0].copy()

    explicit_hof_in_recs = next(
        (_clean_cell_str(r.get("Full Name", "")) for r in records if _clean_cell_str(r.get("Relationship", "")).upper() in ("HEAD OF FAMILY", "HOF")),
        ""
    )
    raw_first_hof = _clean_cell_str(first.get("Head of Family", ""))
    if _is_junk_ocr_header_name(raw_first_hof):
        raw_first_hof = ""
    hof_raw = raw_first_hof or explicit_hof_in_recs or _clean_cell_str(first.get("Full Name", ""))

    def_brgy = _clean_ocr_place_names(first.get("Barangay", ""), matched_p)
    def_city = _clean_ocr_place_names(first.get("City/Municipality", ""), matched_p)
    def_prov = _clean_ocr_place_names(first.get("Province / Area", ""), matched_p)
    def_zip = _clean_cell_str(first.get("ZIP Code", ""))
    if not is_hk:
        if not def_brgy and matched_p in ("LIPAY NORTE PARISH", "POBLACION PARISH", "MALANAS PARISH", "DUPLAS PARISH"):
            def_brgy = matched_p.replace("PARISH", "").strip().title()
        if not def_city and matched_p in ("LIPAY NORTE PARISH", "POBLACION PARISH", "MALANAS PARISH", "DUPLAS PARISH"):
            def_city = "San Gabriel"
        if not def_prov and matched_p in ("LIPAY NORTE PARISH", "POBLACION PARISH", "MALANAS PARISH", "DUPLAS PARISH", "CABA PARISH"):
            def_prov = "La Union"
        if not def_zip:
            def_zip = infer_philippine_postal_zip_code(matched_p, def_city, def_brgy, def_prov) or "2513"

    def_house = _clean_ocr_place_names(first.get("House / Street / Purok", ""), matched_p)
    if not def_house and not is_hk:
        def_house = ", ".join([x for x in [def_brgy, def_city, def_prov] if x])
    full_addr = ", ".join([x for x in [def_house, def_brgy, def_city, def_prov] if x and x.upper() not in def_house.upper()])
    if def_house:
        full_addr = def_house if not full_addr else f"{def_house}, {full_addr}"

    has_spouse = any(
        _clean_cell_str(r.get("Relationship", "")).upper() in ("WIFE", "WF", "HUSBAND", "HBD")
        for r in records
    )
    shared_fid = _clean_cell_str(first.get("Family ID", ""))
    shared_area = _clean_cell_str(first.get("Area/Zone", ""))
    shared_cell = _clean_cell_str(first.get("Cell Group", ""))
    shared_em_n = _clean_cell_str(first.get("Emergency Contact Name", ""))
    shared_em_r = _clean_cell_str(first.get("Emergency Relationship", ""))
    shared_em_c = _clean_cell_str(first.get("Emergency Contact Number", ""))
    shared_rem = _clean_cell_str(first.get("Remarks", ""))

    cleaned_list = []
    for idx_r, r_in in enumerate(records, 1):
        r = _normalize_ctg_form_codes(r_in.copy())
        fn_m = _clean_cell_str(r.get("Full Name", ""))
        if not fn_m or _is_junk_ocr_header_name(fn_m):
            continue
        fn_m = re.sub(r"[/\\|]+$", "", fn_m).strip(" ,.-")
        rel_u = _clean_cell_str(r.get("Relationship", "")).upper()
        is_this_hof = bool(hof_raw and not is_hk and _is_same_head_of_family_fuzzy(fn_m, hof_raw))
        # STRICT VERBATIM COPY-PASTE RULE:
        # NEVER rewrite, alter, or force-harmonize a member's surname to match the Head of Family!
        if is_this_hof:
            fn_m = hof_raw
            if rel_u in ("HUSBAND", "HBD", "DEPENDENT", "", "HEAD OF FAMILY"):
                rel_u = "HEAD OF FAMILY"
        elif rel_u == "HEAD OF FAMILY":
            if not hof_raw and not is_hk:
                hof_raw = fn_m
                is_this_hof = True
            elif hof_raw and not is_hk and not is_this_hof:
                rel_u = "DEPENDENT"
        elif not rel_u:
            rel_u = "HEAD OF FAMILY" if (idx_r == 1 and not hof_raw) else "DEPENDENT"
        r["Parish"] = matched_p
        r["Family ID"] = _clean_cell_str(r.get("Family ID", "")) or shared_fid
        r["Area/Zone"] = _clean_cell_str(r.get("Area/Zone", "")) or shared_area
        r["Cell Group"] = _clean_cell_str(r.get("Cell Group", "")) or shared_cell
        r["Head of Family"] = fn_m if is_hk else (hof_raw or fn_m)
        r["No."] = str(idx_r)
        r["Full Name"] = fn_m
        r["Relationship"] = "HEAD OF FAMILY" if is_hk else rel_u

        sex_u = _clean_cell_str(r.get("Sex", "")).upper()
        if rel_u in ("WIFE", "DAUGHTER", "DAUGHTER IN LAW", "MOTHER", "SISTER", "GRANDMOTHER", "GRANDDAUGHTER"):
            sex_u = "FEMALE"
        elif rel_u in ("HUSBAND", "SON", "SON IN LAW", "FATHER", "BROTHER", "GRANDFATHER", "GRANDSON"):
            sex_u = "MALE"
        elif sex_u not in ("MALE", "FEMALE"):
            sex_u = "FEMALE" if any(w in fn_m.upper().split() for w in ["ANA", "LIZA", "MARIA", "MARY", "MERCY", "MAY-ANN", "ELLA", "MARIELOU", "ROSA", "ELENA", "GRACE"]) else "MALE"
        r["Sex"] = sex_u

        age_s = _clean_cell_str(r.get("Age", ""))
        bd_iso = _normalize_handwritten_date_to_iso(r.get("Birthdate", ""), age_hint=age_s)
        r["Birthdate"] = bd_iso
        if bd_iso and re.match(r"^\d{4}-\d{2}-\d{2}$", bd_iso):
            try:
                by = int(bd_iso.split("-")[0])
                bm = int(bd_iso.split("-")[1])
                if 1915 <= by <= 2026:
                    calc_age = max(0, 2026 - by - (1 if bm >= 11 else 0))
                    if not age_s or not age_s.isdigit() or abs(int(age_s) - calc_age) > 1:
                        age_s = str(calc_age)
            except Exception:
                pass
        r["Age"] = age_s

        cat_u = _clean_cell_str(r.get("Category", "")).upper()
        if age_s.isdigit():
            av = int(age_s)
            if av >= 60:
                cat_u = "SENIOR CITIZEN"
            elif av >= 25:
                cat_u = "ADULT"
            elif av >= 13:
                cat_u = "YOUTH"
            else:
                cat_u = "KID"
        if not cat_u:
            cat_u = "KID" if rel_u in ("SON", "DAUGHTER") and not age_s else "ADULT"
        if is_hk and cat_u in ("YOUTH", "KID", "KID"):
            cat_u = "ADULT"
        r["Category"] = cat_u

        civ_u = _clean_cell_str(r.get("Civil Status", "")).upper()
        if rel_u in ("WIFE", "HUSBAND") or (is_this_hof and has_spouse and civ_u not in ("WIDOWED", "SEPARATED")):
            civ_u = "MARRIED"
        elif cat_u in ("KID", "YOUTH") and rel_u in ("SON", "DAUGHTER", "GRANDSON", "GRANDDAUGHTER", "DEPENDENT", ""):
            civ_u = "SINGLE"
        elif not civ_u:
            civ_u = "MARRIED" if is_this_hof else "SINGLE"
        r["Civil Status"] = civ_u

        r["House / Street / Purok"] = _clean_ocr_place_names(r.get("House / Street / Purok", ""), matched_p) or def_house
        r["Barangay"] = _clean_ocr_place_names(r.get("Barangay", ""), matched_p) or def_brgy
        r["City/Municipality"] = _clean_ocr_place_names(r.get("City/Municipality", ""), matched_p) or def_city
        r["Province / Area"] = _clean_ocr_place_names(r.get("Province / Area", ""), matched_p) or def_prov
        r["ZIP Code"] = _clean_cell_str(r.get("ZIP Code", "")) or def_zip
        r["Current Address (If living separately)"] = _clean_ocr_place_names(r.get("Current Address (If living separately)", ""), matched_p) or full_addr or def_house
        r["Emergency Contact Name"] = _clean_cell_str(r.get("Emergency Contact Name", "")) or shared_em_n
        r["Emergency Relationship"] = _clean_cell_str(r.get("Emergency Relationship", "")) or shared_em_r
        r["Emergency Contact Number"] = _clean_cell_str(r.get("Emergency Contact Number", "")) or shared_em_c
        sw_cur = _clean_cell_str(r.get("Student/Working", "")).upper()
        if sw_cur in ("N", "N/A", "NA", "NONE", "WALANG TRABAHO", "UNEMPLOYED"):
            r["Student/Working"] = "NONE"
        elif cat_u == "SENIOR CITIZEN" and not sw_cur:
            r["Student/Working"] = "NONE"
        elif cat_u == "KID" or (cat_u == "YOUTH" and civ_u == "SINGLE" and rel_u in ("SON", "DAUGHTER", "GRANDSON", "GRANDDAUGHTER") and (not age_s.isdigit() or int(age_s) <= 19)):
            if age_s.isdigit() and int(age_s) < 4:
                r["Student/Working"] = "NONE"
            elif sw_cur in ("", "WORKING"):
                r["Student/Working"] = "STUDENT"
        r["Remarks"] = _clean_cell_str(r.get("Remarks", "")) or shared_rem
        cleaned_list.append(_normalize_ctg_form_codes(r))

    # Deduplicate fuzzy OCR duplicates (e.g. 'Jacelle Tae Timbreza' + 'Jacelle Mae Timbreza', or 'Sushane' + 'Sushane Niña')
    if len(cleaned_list) > 1 and not is_hk:
        deduped = []
        for cand in cleaned_list:
            c_nm = _clean_cell_str(cand.get("Full Name", ""))
            c_up = re.sub(r"[^A-Z\s]", "", c_nm.upper()).strip()
            c_alpha = re.sub(r"[^A-Z]", "", c_up)
            # Skip single-word fragments like 'Sushane' if another row starts with that word + more words (e.g. 'Sushane Ni' / 'Sushane Niña')
            if len(c_up.split()) == 1 and any(
                other is not cand
                and len(_clean_cell_str(other.get("Full Name", "")).split()) >= 2
                and _clean_cell_str(other.get("Full Name", "")).upper().startswith(c_up + " ")
                for other in cleaned_list
            ):
                for other in cleaned_list:
                    if other is not cand and _clean_cell_str(other.get("Full Name", "")).upper().startswith(c_up + " "):
                        for fk in ("Birthdate", "Age", "Category", "Contact No.", "Relationship", "Civil Status", "Student/Working"):
                            if (not _clean_cell_str(other.get(fk, "")) or other.get(fk) == "DEPENDENT") and _clean_cell_str(cand.get(fk, "")):
                                other[fk] = cand[fk]
                continue

            matched_existing = None
            for ex in deduped:
                ex_nm = _clean_cell_str(ex.get("Full Name", ""))
                ex_alpha = re.sub(r"[^A-Z]", "", ex_nm.upper())
                sim = difflib.SequenceMatcher(None, c_alpha, ex_alpha).ratio()
                same_bday = bool(cand.get("Birthdate") and ex.get("Birthdate") and cand.get("Birthdate") == ex.get("Birthdate"))
                if sim >= 0.82 or (same_bday and sim >= 0.65) or (len(c_alpha) >= 6 and (c_alpha in ex_alpha or ex_alpha in c_alpha)):
                    matched_existing = ex
                    break
            if matched_existing is not None:
                # Prefer name without common OCR typo ('Jacelle Mae' over 'Jacelle Tae', longer full name over truncated)
                ex_nm_cur = _clean_cell_str(matched_existing.get("Full Name", ""))
                if (len(c_nm) > len(ex_nm_cur)) or (" TAE " in ex_nm_cur.upper() and " MAE " in c_nm.upper()):
                    matched_existing["Full Name"] = c_nm
                cand_rel_c = _clean_cell_str(cand.get("Relationship", "")).upper()
                ex_rel_c = _clean_cell_str(matched_existing.get("Relationship", "")).upper()
                if cand_rel_c not in ("", "DEPENDENT") and (ex_rel_c in ("", "DEPENDENT") or (cand_rel_c in ("DAUGHTER", "SON", "WIFE", "HUSBAND") and ex_rel_c == "HEAD OF FAMILY" and not _is_same_head_of_family_fuzzy(matched_existing.get("Full Name", ""), hof_raw))):
                    matched_existing["Relationship"] = cand_rel_c
                    if cand_rel_c in ("WIFE", "DAUGHTER", "DAUGHTER IN LAW", "MOTHER", "SISTER", "GRANDMOTHER", "GRANDDAUGHTER"):
                        matched_existing["Sex"] = "FEMALE"
                    elif cand_rel_c in ("HUSBAND", "SON", "SON IN LAW", "FATHER", "BROTHER", "GRANDFATHER", "GRANDSON"):
                        matched_existing["Sex"] = "MALE"
                for fk in ("Birthdate", "Age", "Category", "Contact No.", "Civil Status", "Student/Working"):
                    if not _clean_cell_str(matched_existing.get(fk, "")) and _clean_cell_str(cand.get(fk, "")):
                        matched_existing[fk] = cand[fk]
                if matched_existing.get("Category") in ("YOUTH", "KID") and matched_existing.get("Relationship") in ("DAUGHTER", "SON", "GRANDDAUGHTER", "GRANDSON"):
                    matched_existing["Civil Status"] = "SINGLE"
                    if int(matched_existing.get("Age", "0") or 0) >= 4:
                        matched_existing["Student/Working"] = "STUDENT"
                elif matched_existing.get("Relationship") == "WIFE":
                    matched_existing["Civil Status"] = "MARRIED"
            else:
                deduped.append(cand)
        cleaned_list = deduped

    # Sort so HEAD OF FAMILY is always Row 1, WIFE/HUSBAND is Row 2, and children/dependents follow in table/age order
    if len(cleaned_list) > 1 and not is_hk:
        def _row_sort_priority(r_item):
            rel_s = _clean_cell_str(r_item.get("Relationship", "")).upper()
            nm_s = _clean_cell_str(r_item.get("Full Name", ""))
            if rel_s == "HEAD OF FAMILY" or (hof_raw and _is_same_head_of_family_fuzzy(nm_s, hof_raw)):
                return (0, 0)
            if rel_s in ("WIFE", "HUSBAND"):
                return (1, 0)
            ag_s = _clean_cell_str(r_item.get("Age", ""))
            ag_num = -int(ag_s) if ag_s.isdigit() else 0
            return (2, ag_num)
        cleaned_list.sort(key=_row_sort_priority)

    # Enforce 1 unified Head of Family, sequential No. 1..N, and 1 unified Family ID across the entire family batch (for non-HK parishes)
    if cleaned_list and not is_hk:
        unified_hof = hof_raw or cleaned_list[0].get("Full Name", "")
        for idx_u, item_u in enumerate(cleaned_list, 1):
            item_u["Head of Family"] = unified_hof
            item_u["No."] = str(idx_u)
            if idx_u == 1 and _clean_cell_str(item_u.get("Relationship", "")).upper() in ("HUSBAND", "DEPENDENT", ""):
                item_u["Relationship"] = "HEAD OF FAMILY"
            if shared_fid:
                item_u["Family ID"] = shared_fid

    return cleaned_list

def _extract_clean_person_name_from_filename(filename: str) -> str:
    """Extracts a clean Head of Family name from scanned PDF/image filenames like
    'Ana Liza B Abutin CTG20261120_22410249.pdf' -> 'Ana Liza B. Abutin'."""
    base = os.path.splitext(os.path.basename(str(filename or "")))[0]
    base = re.sub(r"^CTG_Form_[A-Za-z_]+_", "", base, flags=re.I)
    base = re.sub(r"CTG\s*\d+[_0-9\-]*.*$", "", base, flags=re.I).strip()
    base = re.sub(r"(?:202\d|19\d\d)[_0-9\-]+.*$", "", base).strip()
    base = re.sub(r"[_\-]+", " ", base).strip()
    base = re.sub(r"\d+", " ", base).strip()
    base = re.sub(r"\s+", " ", base).strip()
    stop_words = {"form", "scan", "page", "pdf", "image", "img", "sample", "test", "upload", "copy", "ctg"}
    parts = [p for p in base.split() if p.lower().strip(".") not in stop_words]
    formatted_parts = []
    for p in parts:
        p_c = p.strip(".")
        if len(p_c) == 1 and p_c.isalpha():
            formatted_parts.append(f"{p_c.upper()}.")
        else:
            formatted_parts.append(p.title())
    cand_name = " ".join(formatted_parts).strip()
    return cand_name if len(cand_name) >= 4 else ""


