def _perform_clean_user_logout() -> None:
    record_security_audit_event(
        "AUTH_LOGOUT",
        f"User '{st.session_state.get('logged_in_username', '')}' logged out cleanly",
        severity="INFO",
        outcome="SUCCESS",
    )
    if st.session_state.get("login_role") != "Master Admin":
        set_parish_leader_offline_presence(
            st.session_state.get("login_parish") or st.session_state.get("assigned_parish", "")
        )
    st.session_state.authenticated = False
    st.session_state.pop("_session_csrf_token", None)
    st.rerun()


def _refresh_live_app_data_preserving_state() -> None:
    """Refreshes live Excel/Notion/Chat data without clearing auth or resetting the user's current page/form state."""
    try:
        load_internal_chat_messages(sync_cloud=True)
    except Exception:
        pass
    try:
        fetch_live_excel_bytes(ACTIVE_SPREADSHEET_URL, force_cloud=True)
    except Exception:
        pass
    try:
        load_complete_parish_members.clear()
    except Exception:
        pass
    try:
        load_weekly_monitoring_records.clear()
    except Exception:
        pass


inject_enterprise_theme_css()

with st.sidebar:
    if st.session_state.user_role != "Master Admin":
        record_parish_leader_active_presence(st.session_state.assigned_parish)
    _ldr_profiles_sb = load_leadership_and_priests_profiles()
    _is_master_sb = (st.session_state.user_role == "Master Admin")
    _is_true_master_sb = (st.session_state.get("login_role") == "Master Admin")
    _is_dio_sb = is_current_user_diocese_admin()

    # Resolve Display Name, Role, Scope & Avatar
    if _is_master_sb:
        _sb_disp_name = "Master Admin"
        _sb_role_lbl = "Master Admin"
        _sb_scope_lbl = "All Parishes (Global)"
        _sb_avatar_uri = ""
