def _get_online_leaders_summary() -> list[dict]:
    profiles_top = load_leadership_and_priests_profiles()
    ph_now_str = get_philippine_datetime_str()
    online_list = [{"name": "Master Admin", "role": "System Administrator", "scope": "All Parishes", "time": ph_now_str}]
    dio1_t = profiles_top.get("diocese_head_1", {})
    dio2_t = profiles_top.get("diocese_head_2", {})
    if (get_current_diocese_scope_key() == DIOCESE_1_KEY) or (bool(dio1_t.get("is_active_online")) and (time.time() - float(dio1_t.get("last_active_epoch", 0) or 0)) <= 1800.0):
        online_list.append({
            "name": dio1_t.get("name", DIOCESE_1_LEADER_NAME),
            "role": dio1_t.get("position", "Diocese Head I"),
            "scope": "Region 1 + Manila/HK",
            "time": dio1_t.get("last_active_ph", ph_now_str),
        })
    if (get_current_diocese_scope_key() == DIOCESE_2_KEY) or (bool(dio2_t.get("is_active_online")) and (time.time() - float(dio2_t.get("last_active_epoch", 0) or 0)) <= 1800.0):
        online_list.append({
            "name": dio2_t.get("name", DIOCESE_2_LEADER_NAME),
            "role": dio2_t.get("position", "Diocese Head 2"),
            "scope": "Region 2 (Andabuen & Apayao)",
            "time": dio2_t.get("last_active_ph", ph_now_str),
        })
    priests_top = profiles_top.get("parish_priests", {})
    for p_k in PARISH_ORDER:
        p_inf = priests_top.get(p_k, {})
        if is_parish_leader_currently_online(p_inf, p_k):
            online_list.append({
                "name": p_inf.get("name", p_k),
                "role": p_inf.get("position", get_default_parish_leader_role_title(p_k)),
                "scope": p_k,
                "time": p_inf.get("last_active_ph", ph_now_str),
            })
    return online_list


def _compute_role_scoped_dashboard_data() -> dict:
    """Computes strictly role-scoped real backend metrics for Master Admin, Diocese Admin, or Parish Leader."""
    is_master = (st.session_state.user_role == "Master Admin")
    is_dio = is_current_user_diocese_admin()
    dio_allowed = get_allowed_parishes_for_current_user()
    assigned_p = str(st.session_state.assigned_parish or "").strip()

    if is_master:
        scope_label = "All 10 Parishes (Global Master View)"
        allowed_parishes = list(PARISH_ORDER)
    elif is_dio:
        scope_label = f"{get_current_diocese_scope_key()} ({len(dio_allowed)} Parishes — Active: {assigned_p})"
        allowed_parishes = list(dio_allowed)
    else:
        scope_label = assigned_p
        allowed_parishes = [assigned_p] if assigned_p else []

    if not master_members_df.empty and "Parish" in master_members_df.columns:
        df_scope = (
            master_members_df.copy()
            if is_master else (
                master_members_df[master_members_df["Parish"].isin(allowed_parishes)].copy()
            )
        )
    else:
        df_scope = pd.DataFrame()

    tot_families = df_scope["Family ID"].replace("", pd.NA).dropna().nunique() if not df_scope.empty and "Family ID" in df_scope.columns else 0
    tot_members = len(df_scope)
    if not df_scope.empty:
        act_mask = df_scope.apply(
            lambda r: (not is_removed_or_deceased_record(r)) and classify_member_status(r.get("Status", ""), r.get("Church Member", "")) == "ACTIVE",
            axis=1,
        )
        df_active = df_scope[act_mask]
        active_adults_seniors = sum(1 for _, r in df_active.iterrows() if classify_category(r.get("Category", "")) in ("Adults", "Seniors"))
        active_youth_kids = sum(1 for _, r in df_active.iterrows() if classify_category(r.get("Category", "")) in ("Youth", "Kid"))
    else:
        df_active = pd.DataFrame()
        active_adults_seniors = 0
        active_youth_kids = 0

    # Pending requests & activity scoped by role
    if not global_records_df.empty and "Parokya" in global_records_df.columns:
        if is_master:
            df_reqs = global_records_df.copy()
        else:
            df_reqs = global_records_df[global_records_df["Parokya"].isin(allowed_parishes)].copy()
        pending_approvals = len(df_reqs[df_reqs["Status"].str.contains("For Master Admin Approval|Assigned to Parish Leader|Pending", case=False, na=False)])
    else:
        df_reqs = pd.DataFrame()
        pending_approvals = 0

    # Weekly reports count
    weekly_db = load_weekly_monitoring_records()
    weekly_completed = 0
    for k_wk, v_wk in weekly_db.items():
        p_part = str(k_wk).split("__")[0].strip().upper()
        if (is_master or any(p_part == ap.upper() for ap in allowed_parishes)) and is_week_record_completed(v_wk):
            weekly_completed += 1

    # Recent activity feed items from live notifications / requests
    notifs = load_live_notifications()
    recent_feed = []
    for nf in reversed(notifs[-6:]):
        sender = str(nf.get("sender", ""))
        if is_master or any(ap.lower() in sender.lower() for ap in allowed_parishes) or "master" in sender.lower():
            recent_feed.append({
                "title": nf.get("title", "System Update"),
                "actor": sender or "System",
                "timestamp": nf.get("timestamp", ""),
                "detail": nf.get("details", ""),
                "tone": "danger" if nf.get("is_error") else "info",
            })

    return {
        "is_master": is_master,
        "is_dio": is_dio,
        "scope_label": scope_label,
        "allowed_parishes": allowed_parishes,
        "df_scope": df_scope,
        "df_active": df_active,
        "tot_families": tot_families,
        "tot_members": tot_members,
        "active_members": len(df_active),
        "active_adults_seniors": active_adults_seniors,
        "active_youth_kids": active_youth_kids,
        "pending_approvals": pending_approvals,
        "weekly_completed": weekly_completed,
        "recent_feed": recent_feed,
        "unread_notifs": len(notifs),
    }


